'use strict';
const KEY='project-archive-draft-v1';
let editingReleaseId=null,editingResourceId=null;
const $=s=>document.querySelector(s);
const original=window.ARCHIVE_DATA;
let draft=JSON.parse(JSON.stringify(original));
const baseReleaseIDs=new Set(original.releases.map(r=>r.id)),baseResourceIDs=new Set(original.resources.map(r=>r.id));
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const status=message=>{$('#editor-status').textContent=message;};
function validate(data){if(!data||data.schemaVersion!==1||!data.site||typeof data.site.updated!=='string'||!Array.isArray(data.projects)||!Array.isArray(data.documents)||!Array.isArray(data.resources)||!Array.isArray(data.releases))throw Error('Project Archive 데이터 형식을 확인해 주세요.');for(const key of ['projects','documents','resources','releases']){const ids=new Set();for(const row of data[key]){if(!row||typeof row.id!=='string'||ids.has(row.id))throw Error('누락되거나 중복된 ID가 있습니다.');ids.add(row.id);}}const a=data.site.aiDevelopment;if(a?.markdown!==undefined&&(typeof a.markdown!=='string'||a.markdown.length>2000000))throw Error('Markdown 문서는 2MB 이하의 텍스트여야 합니다.');if(a&&(!(typeof a.title==='string'&&a.title.trim())||typeof a.intro!=='string'||!Array.isArray(a.responsibilities)||!a.responsibilities.every(v=>typeof v==='string')||!['tools','steps'].every(k=>Array.isArray(a[k])&&a[k].every(row=>Array.isArray(row)&&row.length===2&&row.every(v=>typeof v==='string')))))throw Error('AI 활용 내용 형식을 확인해 주세요.');const pids=new Set(data.projects.map(p=>p.id));for(const p of data.projects){const b=p.brief;if(b&&(!Array.isArray(b.title)||!b.title.length||!b.title.every(v=>typeof v==='string')||!Array.isArray(b.points)||!b.points.every(v=>typeof v==='string')||!['steps','build'].every(key=>Array.isArray(b[key])&&b[key].length&&b[key].every(row=>Array.isArray(row)&&row.length===2&&row.every(v=>typeof v==='string')))||!Array.isArray(b.featured)||!b.featured.every(id=>data.documents.some(d=>d.id===id))))throw Error('프로젝트 소개 형식을 확인해 주세요.');}for(const p of data.projects)if(!p.name||!p.short||typeof p.cover!=='string')throw Error('프로젝트 정보가 올바르지 않습니다.');for(const d of data.documents){if(!pids.has(d.project)||!Array.isArray(d.sections)||!Array.isArray(d.images)||!d.title||(!d.file&&d.format!=='WEB')||!d.format||!d.sections.length)throw Error('문서 정보가 올바르지 않습니다.');for(const s of d.sections){if(!Array.isArray(s.blocks))throw Error('문서 본문 형식이 올바르지 않습니다.');for(const b of s.blocks)if((b.type==='image'&&typeof b.src==='string'&&typeof b.alt==='string'&&typeof b.caption==='string')||(b.type==='video'&&typeof b.src==='string'&&typeof b.title==='string'&&typeof b.caption==='string')||(b.type==='link'&&typeof b.url==='string'&&typeof b.label==='string'&&typeof b.description==='string')||(b.type==='text'&&typeof b.text==='string')||(b.type==='table'&&Array.isArray(b.rows)&&b.rows.length&&b.rows.every(row=>Array.isArray(row)&&row.every(c=>typeof c==='string')))){}else throw Error('문서 본문 형식이 올바르지 않습니다.');}}for(const r of data.resources)if(!r.name||!r.type||!Array.isArray(r.projects)||!r.projects.every(p=>pids.has(p)))throw Error('리소스 정보가 올바르지 않습니다.');for(const r of data.releases)if(!r.title||!r.version||!/^\d{4}-\d{2}-\d{2}$/.test(r.date)||!Array.isArray(r.changes)||!r.changes.every(c=>typeof c.text==='string'&&typeof c.type==='string')||!(r.project==='site'||pids.has(r.project)))throw Error('변경 기록의 형식이 올바르지 않습니다.');return data;}
try{const saved=localStorage.getItem(KEY);if(saved)draft=validate(JSON.parse(saved));}catch{status('저장된 초안을 읽지 못해 공개 데이터를 불러왔습니다.');}
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
$('#release-form [name=date]').value=today();
function persist(next,message){try{validate(next);localStorage.setItem(KEY,JSON.stringify(next));draft=next;render();scheduleLivePreview();status(message+' 이 브라우저에 저장되었습니다.');return true;}catch(e){status('저장하지 못했습니다: '+e.message);return false;}}
function render(){const releases=draft.releases.filter(r=>!baseReleaseIDs.has(r.id));const resources=draft.resources.filter(r=>!baseResourceIDs.has(r.id));$('#draft-releases').innerHTML=releases.map(r=>`<div class="draft-row"><span>${esc(r.version)} · ${esc(r.title)}<small>${esc(r.date)} · ${esc(r.project)} · 로컬 초안</small></span><button data-remove-release="${esc(r.id)}" type="button">삭제</button></div>`).join('');$('#draft-resources').innerHTML=resources.map(r=>`<div class="draft-row"><span>${esc(r.name)}<small>${esc(r.type)} · ${esc(r.version)} · 로컬 초안</small></span><button data-remove-resource="${esc(r.id)}" type="button">삭제</button></div>`).join('');}
function safePath(value){const raw=String(value||'').trim();if(!raw)return '';if(raw.startsWith('//')||raw.startsWith('\\')||/[\u0000-\u001f]/.test(raw))throw Error('올바른 경로나 https URL을 입력해 주세요.');const url=new URL(raw,location.href);if(!['https:','http:','file:'].includes(url.protocol))throw Error('실행 가능한 URL은 리소스로 사용할 수 없습니다.');return raw;}
$('#release-form').addEventListener('submit',e=>{e.preventDefault();const form=e.target;const fd=new FormData(form);const changes=String(fd.get('changes')).split('\n').map(s=>s.trim()).filter(Boolean).map(line=>{const m=line.match(/^(추가|변경|수정|삭제|문서)\s*[:：]\s*(.+)$/);return{type:m?m[1]:'변경',text:m?m[2]:line};});if(!changes.length){status('변경 항목을 한 개 이상 작성해 주세요.');return;}const row={id:editingReleaseId||'release-'+crypto.randomUUID(),project:fd.get('project'),version:String(fd.get('version')).trim(),date:fd.get('date'),title:String(fd.get('title')).trim(),summary:String(fd.get('summary')).trim(),changes};if(!row.title||!row.version||!row.summary){status('공백이 아닌 제목·버전·요약을 작성해 주세요.');return;}const next=JSON.parse(JSON.stringify(draft));if(editingReleaseId){const index=next.releases.findIndex(r=>r.id===editingReleaseId);next.releases[index]=row;}else next.releases.unshift(row);next.site.updated=today();if(persist(next,'변경 기록을 저장했습니다.')){editingReleaseId=null;form.reset();form.querySelector('[name=date]').value=today();}});
$('#resource-form').addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(e.target);try{const row={...draft.resources.find(r=>r.id===editingResourceId),id:editingResourceId||'resource-'+crypto.randomUUID(),name:String(fd.get('name')).trim(),projects:[fd.get('project')],type:fd.get('type'),file:safePath(fd.get('file')),preview:safePath(fd.get('preview')),version:String(fd.get('version')).trim(),source:String(fd.get('source')).trim(),license:String(fd.get('license')).trim(),note:String(fd.get('note')).trim(),sourceDocs:draft.resources.find(r=>r.id===editingResourceId)?.sourceDocs||[],width:draft.resources.find(r=>r.id===editingResourceId)?.width||null,height:draft.resources.find(r=>r.id===editingResourceId)?.height||null,bytes:pendingAssets.get(safePath(fd.get('file')))?.bytes.length||draft.resources.find(r=>r.id===editingResourceId)?.bytes||null};if(!row.name||!row.version||!row.source||!row.license)throw Error('공백이 아닌 리소스 정보를 작성해 주세요.');const next=JSON.parse(JSON.stringify(draft));if(editingResourceId){const index=next.resources.findIndex(r=>r.id===editingResourceId);next.resources[index]=row;}else next.resources.unshift(row);next.site.updated=today();if(persist(next,'리소스를 저장했습니다.')){e.target.reset();editingResourceId=null;}}catch(err){status(err.message);}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-remove-release],[data-remove-resource]');if(!b)return;const next=JSON.parse(JSON.stringify(draft));if(b.dataset.removeRelease)next.releases=next.releases.filter(r=>r.id!==b.dataset.removeRelease);else next.resources=next.resources.filter(r=>r.id!==b.dataset.removeResource);persist(next,'초안 항목을 삭제했습니다.');});
$('#export-data').addEventListener('click',()=>{try{validate(draft);const output='window.ARCHIVE_DATA = '+JSON.stringify(draft,null,2)+';\n';const blob=new Blob([output],{type:'text/javascript;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='site-data.js';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);status('데이터 파일을 내려받았습니다. 저장소의 public/data/site-data.js를 교체한 후 커밋하면 공유됩니다.');}catch(e){status(e.message);}});
$('#import-data').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>15*1024*1024)throw Error('15MB 이하의 데이터 파일을 선택해 주세요.');const raw=(await file.text()).replace(/^\uFEFF/,'').trim();const json=raw.startsWith('window.ARCHIVE_DATA')?raw.replace(/^window\.ARCHIVE_DATA\s*=\s*/,'').replace(/;\s*$/,''):raw;const imported=validate(JSON.parse(json));if(!confirm('가져온 데이터로 이 브라우저의 초안을 대체할까요?'))return;if(persist(imported,'데이터를 가져왔습니다.'))reloadStructuredEditors();}catch(err){status('가져오지 못했습니다: '+err.message);}e.target.value='';});
$('#reset-draft').addEventListener('click',()=>{if(confirm('이 브라우저의 초안을 지우고 현재 공개 데이터로 되돌릴까요?'))if(persist(JSON.parse(JSON.stringify(original)),'공개 데이터로 초기화했습니다.'))reloadStructuredEditors();});
render();

// Structured copy editing and user-selected local repository access.
const clone=value=>JSON.parse(JSON.stringify(value));
const formField=(form,name)=>form.querySelector('[name="'+name+'"]');
let selectedProjectId=draft.projects[0].id,selectedDocumentId=draft.documents[0].id,selectedSectionIndex=0;
let repositoryHandle=null,publicHandle=null,loadedSourcePath='';
const stagedFiles=new Map(),pendingAssets=new Map();
const SOURCE_FILES=new Set(['styles.css','index.html','app.js','editor.html','editor.js']);
try{for(const [path,text] of JSON.parse(localStorage.getItem(KEY+'-files')||'[]'))if(SOURCE_FILES.has(path)&&typeof text==='string')stagedFiles.set(path,text);}catch{}
function options(rows,selected,placeholder=''){return (placeholder?'<option value="">'+esc(placeholder)+'</option>':'')+rows.map(([value,label])=>'<option value="'+esc(value)+'" '+(value===selected?'selected':'')+'>'+esc(label)+'</option>').join('');}
function refreshEditorLists(){
 $('#project-select').innerHTML=options(draft.projects.map(p=>[p.id,p.name]),selectedProjectId);
 $('#document-select').innerHTML=options(draft.documents.map(d=>[d.id,(draft.projects.find(p=>p.id===d.project)?.name||'')+' · '+d.title]),selectedDocumentId);
 $('#release-select').innerHTML=options(draft.releases.map(r=>[r.id,r.version+' · '+r.title]),editingReleaseId,'새 변경 기록');
 $('#resource-select').innerHTML=options(draft.resources.map(r=>[r.id,r.name]),editingResourceId,'새 리소스');
}
function loadProject(){const p=draft.projects.find(p=>p.id===selectedProjectId);const b=p.brief||original.projects.find(base=>base.id===p.id)?.brief;const form=$('#project-form');const values={name:p.name,genre:p.genre,cardText:p.cardText||'',cover:p.cover,title:(b?.title||[p.name]).join('\n'),label:b?.label||'',tagline:b?.tagline||p.description||'',concept:b?.concept||'',points:(b?.points||[]).join('\n'),steps:(b?.steps||[]).map(row=>row.join(' | ')).join('\n'),build:(b?.build||[]).map(row=>row.join(' | ')).join('\n')};for(const [name,value]of Object.entries(values))formField(form,name).value=value;loadCoverFields(form,p);}
function loadAI(){const a={...original.site.aiDevelopment,...draft.site.aiDevelopment};if(!a.title)return;const form=$('#ai-form');for(const name of ['title','intro','markdown'])formField(form,name).value=a[name]||'';formField(form,'responsibilities').value=a.responsibilities.join('\n');for(const name of ['tools','steps'])formField(form,name).value=a[name].map(row=>row.join(' | ')).join('\n');}
function readAI(){const form=$('#ai-form'),read=name=>formField(form,name).value;return {title:read('title'),intro:read('intro'),markdown:read('markdown'),responsibilities:parseLines(read('responsibilities')),tools:previewPairs(read('tools')),steps:previewPairs(read('steps'))};}
function prepareAIMarkdown(text){if(typeof text!=='string'||text.length>2000000)throw Error('2MB 이하의 Markdown 문서를 선택해 주세요.');const value=text.replace(/^\uFEFF/,'').replace(/\r\n?/g,'\n');if(!value.trim())throw Error('비어 있지 않은 문서를 선택해 주세요.');return value;}
$('#import-ai-markdown').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2000000)throw Error('2MB 이하의 Markdown 문서를 선택해 주세요.');const text=prepareAIMarkdown(await file.text());formField($('#ai-form'),'markdown').value=text;const title=text.match(/^#\s+(.+)$/m);if(title)formField($('#ai-form'),'title').value=title[1].trim();$('#preview-page').value='ai-development';scheduleLivePreview();status('Markdown을 불러왔습니다. 미리보기를 확인하고 초안 저장을 눌러 주세요.');}catch(error){status(error.message);}e.target.value='';});
$('#ai-image-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('PNG·JPEG·WebP 이미지를 선택해 주세요.');const path=await stageAsset(file),field=formField($('#ai-form'),'markdown'),at=field.selectionStart??field.value.length,end=field.selectionEnd??at,label=file.name.replace(/[\[\]\r\n]/g,'');field.value=field.value.slice(0,at)+'\n!['+label+']('+path+')\n'+field.value.slice(end);$('#preview-page').value='ai-development';scheduleLivePreview();status('Markdown의 커서 위치에 이미지를 넣었습니다. 미리보기를 확인하고 초안을 저장해 주세요.');}catch(error){status(error.message);}e.target.value='';});
$('#export-ai-markdown').addEventListener('click',()=>{try{const text=prepareAIMarkdown(formField($('#ai-form'),'markdown').value),url=URL.createObjectURL(new Blob([text],{type:'text/markdown;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='ai-development.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}catch(error){status(error.message);}});
$('#ai-form').addEventListener('submit',e=>{e.preventDefault();const next=clone(draft);next.site.aiDevelopment=readAI();next.site.updated=today();persist(next,'AI 활용 내용을 저장했습니다.');});
function loadSite(){const form=$('#site-form');for(const name of ['heading','kicker','contactEmail'])formField(form,name).value=draft.site[name]||'';}
function parseLines(value){return String(value).split('\n').map(s=>s.trim()).filter(Boolean);}
function parsePairs(value){const pairs=parseLines(value).map(line=>{const index=line.indexOf('|');if(index<1||!line.slice(index+1).trim())throw Error('제목 | 설명 형식으로 작성해 주세요.');return[line.slice(0,index).trim(),line.slice(index+1).trim()];});if(!pairs.length||pairs.length>10)throw Error('항목은 1~10개로 작성해 주세요.');return pairs;}
function updateProjectFromFields(data,id,values){const next=clone(data),p=next.projects.find(p=>p.id===id);if(!p)throw Error('프로젝트를 찾을 수 없습니다.');for(const name of ['name','genre','cardText','tagline','concept'])if(!String(values[name]||'').trim())throw Error('프로젝트 소개 항목을 작성해 주세요.');p.name=values.name.trim();p.genre=values.genre.trim();p.cardText=values.cardText.trim();p.cover=safePath(values.cover);if(values.coverFit!==undefined)p.coverLayout={fit:values.coverFit==='contain'?'contain':'cover',positionX:mediaNumber(values.coverX,50,0,100),positionY:mediaNumber(values.coverY,50,0,100),heroWidth:mediaNumber(values.heroWidth,p.id==='ww'?67:47,25,80)};p.description=values.tagline.trim();const old=p.brief||original.projects.find(base=>base.id===id)?.brief;p.brief={...old,title:parseLines(values.title),label:String(values.label).trim(),tagline:values.tagline.trim(),concept:values.concept.trim(),points:parseLines(values.points),steps:parsePairs(values.steps),build:parsePairs(values.build)};if(!p.cover||!p.brief.title.length||!p.brief.points.length)throw Error('제목·특징·이미지를 입력해 주세요.');next.site.updated=today();return next;}
$('#project-select').addEventListener('change',e=>{selectedProjectId=e.target.value;loadProject();});
$('#project-form').addEventListener('submit',e=>{e.preventDefault();try{const fd=new FormData(e.target),values={};for(const name of ['name','genre','cardText','cover','title','label','tagline','concept','points','steps','build','coverFit','coverX','coverY','heroWidth'])values[name]=String(fd.get(name)||'');const next=updateProjectFromFields(draft,selectedProjectId,values);if(persist(next,'프로젝트 소개를 저장했습니다.'))refreshEditorLists();}catch(error){status(error.message);}});
$('#site-form').addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(e.target);const email=String(fd.get('contactEmail')||'').trim();if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){status('이메일 주소를 확인해 주세요.');return;}const next=clone(draft);next.site.heading=String(fd.get('heading')||'').trim();next.site.kicker=String(fd.get('kicker')||'').trim();next.site.contactEmail=email;next.site.updated=today();persist(next,'홈 문구와 연락처를 저장했습니다.');});
function applyDocumentFields(data,id,sectionIndex,values){const next=clone(data),doc=next.documents.find(d=>d.id===id),section=doc?.sections[sectionIndex];if(!section)throw Error('문서를 찾을 수 없습니다.');if(!values.title.trim()||!values.sectionTitle.trim())throw Error('문서와 페이지 제목을 작성해 주세요.');doc.title=values.title.trim();doc.kind=values.kind;if(values.cover!==undefined){doc.cover=safePath(values.cover);doc.coverLayout=values.coverLayout;}for(const image of values.images||[]){if(section.blocks[image.index]?.type!=='image')throw Error('이미지 위치를 확인해 주세요.');section.blocks[image.index]={...section.blocks[image.index],type:'image',src:safePath(image.src),alt:image.alt,caption:image.caption,layout:imageLayout(image.layout)};}for(const edit of values.videos||[]){const b=section.blocks[edit.index];if(b?.type!=='video')throw Error('동영상 위치를 확인해 주세요.');Object.assign(b,{src:safePath(edit.src),title:edit.title,caption:edit.caption,layout:imageLayout(edit.layout)});}for(const edit of values.links||[]){const b=section.blocks[edit.index];if(b?.type!=='link')throw Error('링크 위치를 확인해 주세요.');Object.assign(b,{url:safeDocumentLink(edit.url),label:edit.label,description:edit.description});}section.title=values.sectionTitle.trim();for(const edit of values.texts||[]){if(section.blocks[edit.index]?.type!=='text')throw Error('문단 위치가 바뀌었습니다. 다시 불러와 주세요.');section.blocks[edit.index].text=edit.value;if(edit.variant!==undefined){if(['paragraph','heading'].includes(edit.variant))section.blocks[edit.index].variant=edit.variant;else delete section.blocks[edit.index].variant;}}for(const edit of values.cells||[]){const rows=section.blocks[edit.index]?.rows;if(!rows?.[edit.row]||edit.col>=rows[edit.row].length)throw Error('표 위치를 확인해 주세요.');rows[edit.row][edit.col]=edit.value;}next.site.updated=today();return next;}
function collectDocumentFields(){const form=$('#document-form');return{...coverFields(form),videos:[...document.querySelectorAll('.editor-video-block')].map(readVideoBlock),links:[...document.querySelectorAll('.editor-link-block')].map(readLinkBlock),images:[...document.querySelectorAll('.editor-image-block')].map(readImageBlock),title:formField(form,'title').value,kind:formField(form,'kind').value,sectionTitle:formField(form,'sectionTitle').value,texts:[...document.querySelectorAll('.doc-text-edit')].map(el=>({index:Number(el.dataset.block),value:el.value,variant:document.querySelector('.doc-text-style[data-block="'+el.dataset.block+'"]')?.value})),cells:[...document.querySelectorAll('.doc-cell-edit')].map(el=>({index:Number(el.dataset.block),row:Number(el.dataset.row),col:Number(el.dataset.col),value:el.value}))};}
function saveDocumentFields(silent=false){try{const next=applyDocumentFields(draft,selectedDocumentId,selectedSectionIndex,collectDocumentFields());const saved=persist(next,silent?'이전 페이지의 초안을 보관했습니다.':'문서 본문을 저장했습니다.');if(saved)refreshEditorLists();return saved;}catch(error){status(error.message);return false;}}
$('#document-select').addEventListener('change',e=>{const value=e.target.value;if(!saveDocumentFields(true)){e.target.value=selectedDocumentId;return;}selectedDocumentId=value;selectedSectionIndex=0;documentInsertPosition=null;refreshEditorLists();loadDocument();});
$('#section-select').addEventListener('change',e=>{const value=e.target.value;if(!saveDocumentFields(true)){e.target.value=String(selectedSectionIndex);return;}selectedSectionIndex=Number(value);documentInsertPosition=null;loadDocument();});
$('#document-form').addEventListener('submit',e=>{e.preventDefault();saveDocumentFields();});
$('#add-doc-paragraph').addEventListener('click',()=>addAuthoringBlock('text'));
