function parseDataFile(raw){const text=raw.replace(/^\uFEFF/,'').trim();return validate(JSON.parse(text.startsWith('window.ARCHIVE_DATA')?text.replace(/^window\.ARCHIVE_DATA\s*=\s*/,'').replace(/;\s*$/,''):text));}
function serialiseData(){validate(draft);return 'window.ARCHIVE_DATA = '+JSON.stringify(draft,null,2)+';\n';}
function safeRelative(path){const parts=String(path).replaceAll('\\','/').split('/');if(!parts.length||parts.some(p=>!p||p==='.'||p==='..'||p.includes(':'))||path.startsWith('/'))throw Error('저장 경로가 올바르지 않습니다.');return parts;}
async function fileAt(root,path,create=false){const parts=safeRelative(path);let dir=root;for(const name of parts.slice(0,-1))dir=await dir.getDirectoryHandle(name,{create});return dir.getFileHandle(parts.at(-1),{create});}
async function writeWithBackup(root,path,content){const parts=safeRelative(path);let existing=null;try{existing=await(await fileAt(root,path)).getFile();}catch(error){if(error.name!=='NotFoundError')throw error;}if(existing){const backupDir=await root.getDirectoryHandle('.archive-backups',{create:true});const filename=new Date().toISOString().replace(/[:.]/g,'-')+'-'+crypto.randomUUID().slice(0,8)+'-'+parts.join('_');const backup=await backupDir.getFileHandle(filename,{create:true});const output=await backup.createWritable();await output.write(existing);await output.close();}const handle=await fileAt(root,path,true);const stream=await handle.createWritable();await stream.write(content);await stream.close();}
$('#connect-folder').addEventListener('click',async()=>{if(!window.showDirectoryPicker){status('이 브라우저는 폴더 저장을 지원하지 않습니다. 수정 파일 내려받기를 사용해 주세요.');return;}try{const selected=await window.showDirectoryPicker({mode:'readwrite'});let site;try{site=await selected.getDirectoryHandle('public');}catch(error){if(error.name!=='NotFoundError')throw error;site=selected;}await fileAt(site,'data/site-data.js');repositoryHandle=selected;publicHandle=site;$('#folder-status').textContent='연결됨: '+selected.name+(site!==selected?' / public':'');status('폴더를 연결했습니다. 폴더에 저장을 누르면 수정 내용을 씁니다.');}catch(error){if(error.name!=='AbortError')status('폴더를 연결하지 못했습니다: '+error.message);}});
$('#save-folder').addEventListener('click',async()=>{if(!publicHandle){status('먼저 저장소 또는 public 폴더를 연결해 주세요.');return;}const button=$('#save-folder');button.disabled=true;try{await assetsReady;const data=serialiseData();for(const[path,asset]of pendingAssets)await writeWithBackup(publicHandle,path,asset.bytes);for(const[path,text]of stagedFiles)await writeWithBackup(publicHandle,path,text);await writeWithBackup(publicHandle,'data/site-data.js',data);if(draft.site.aiDevelopment?.markdown)await writeWithBackup(publicHandle,'content/ai-development.md',draft.site.aiDevelopment.markdown);status('폴더에 저장했습니다. 이전 파일은 .archive-backups에 보관했습니다. 저장소에 커밋하면 공유됩니다.');}catch(error){status('폴더 저장을 완료하지 못했습니다: '+error.message+' 이미 저장된 파일은 폴더에서 확인할 수 있습니다.');}finally{button.disabled=false;}});
async function openAssetDatabase(){if(!('indexedDB'in window))return null;return new Promise((resolve,reject)=>{const req=window.indexedDB.open('project-archive-editor',1);req.onupgradeneeded=()=>req.result.createObjectStore('assets',{keyPath:'path'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
async function rememberAsset(asset){const db=await openAssetDatabase();if(!db)return;await new Promise((resolve,reject)=>{const tx=db.transaction('assets','readwrite');tx.objectStore('assets').put(asset);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});db.close();}
async function restoreAssets(){try{const db=await openAssetDatabase();if(!db)return;const saved=await new Promise((resolve,reject)=>{const req=db.transaction('assets').objectStore('assets').getAll();req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});for(const asset of saved){safeRelative(asset.path);if(asset.path.startsWith('assets/custom/'))pendingAssets.set(asset.path,asset);}db.close();}catch{status('이전에 선택한 이미지를 복원하지 못했습니다. 필요한 파일을 다시 선택해 주세요.');}}
async function stageAsset(file){const limit=file.type.startsWith('video/')?100:20;if(file.size>limit*1024*1024)throw Error('파일은 '+limit+'MB 이하로 추가해 주세요.');const name=file.name.replace(/[^\p{L}\p{N}._-]/gu,'_');const path='assets/custom/'+crypto.randomUUID().slice(0,8)+'-'+name;const asset={path,bytes:new Uint8Array(await file.arrayBuffer()),type:file.type};pendingAssets.set(path,asset);await rememberAsset(asset);return path;}
$('#project-image-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('PNG·JPEG·WebP 이미지를 선택해 주세요.');formField($('#project-form'),'cover').value=await stageAsset(file);status('이미지를 추가했습니다. 크기·초점을 조절하고 초안을 저장해 주세요.');scheduleLivePreview();}catch(error){status(error.message);}});
