$('#stage-source-file').addEventListener('click',()=>{const path=$('#source-file-select').value;if(path!==loadedSourcePath){status('선택한 파일을 먼저 불러와 주세요.');return;}if(!SOURCE_FILES.has(path)){status('지원하지 않는 파일입니다.');return;}const text=$('#source-file-content').value;try{if(new Blob([text]).size>2*1024*1024)throw Error('텍스트 파일은 2MB 이하로 작성해 주세요.');stagedFiles.set(path,text);localStorage.setItem(KEY+'-files',JSON.stringify([...stagedFiles]));$('#source-file-status').textContent=path+' · 초안 저장됨';status('내부 파일을 초안에 담았습니다. 폴더 저장 또는 내려받기로 반영해 주세요.');scheduleLivePreview();}catch(error){status(error.message);}});
// A dependency-free ZIP store writer packages data, images, and edited source files.
const CRC_TABLE=Array.from({length:256},(_,n)=>{let c=n;for(let i=0;i<8;i++)c=c&1?0xedb88320^(c>>>1):c>>>1;return c>>>0;});
function crc32(bytes){let c=0xffffffff;for(const b of bytes)c=CRC_TABLE[(c^b)&255]^(c>>>8);return(c^0xffffffff)>>>0;}
function buildZip(entries){const encode=new TextEncoder(),locals=[],centrals=[];let offset=0;for(const[path,input]of entries){safeRelative(path);const name=encode.encode(path),bytes=typeof input==='string'?encode.encode(input):input,crc=crc32(bytes);const local=new Uint8Array(30+name.length),lv=new DataView(local.buffer);lv.setUint32(0,0x04034b50,true);lv.setUint16(4,20,true);lv.setUint16(6,0x800,true);lv.setUint16(12,33,true);lv.setUint32(14,crc,true);lv.setUint32(18,bytes.length,true);lv.setUint32(22,bytes.length,true);lv.setUint16(26,name.length,true);local.set(name,30);locals.push(local,bytes);const central=new Uint8Array(46+name.length),cv=new DataView(central.buffer);cv.setUint32(0,0x02014b50,true);cv.setUint16(4,20,true);cv.setUint16(6,20,true);cv.setUint16(8,0x800,true);cv.setUint16(14,33,true);cv.setUint32(16,crc,true);cv.setUint32(20,bytes.length,true);cv.setUint32(24,bytes.length,true);cv.setUint16(28,name.length,true);cv.setUint32(42,offset,true);central.set(name,46);centrals.push(central);offset+=local.length+bytes.length;}const centralSize=centrals.reduce((n,b)=>n+b.length,0),end=new Uint8Array(22),ev=new DataView(end.buffer);ev.setUint32(0,0x06054b50,true);ev.setUint16(8,entries.length,true);ev.setUint16(10,entries.length,true);ev.setUint32(12,centralSize,true);ev.setUint32(16,offset,true);return new Blob([...locals,...centrals,end],{type:'application/zip'});}
$('#export-bundle').addEventListener('click',async()=>{try{await assetsReady;const entries=[['public/data/site-data.js',serialiseData()],...(draft.site.aiDevelopment?.markdown?[['public/content/ai-development.md',draft.site.aiDevelopment.markdown]]:[]),...[...pendingAssets].map(([path,asset])=>['public/'+path,asset.bytes]),...[...stagedFiles].map(([path,text])=>['public/'+path,text])];const blob=buildZip(entries),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='site-edits.zip';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);status('수정 파일을 내려받았습니다. 압축을 저장소 폴더에 풀고 변경 내용을 커밋해 주세요.');}catch(error){status(error.message);}});
function reloadStructuredEditors(){selectedProjectId=draft.projects[0].id;selectedDocumentId=draft.documents[0].id;selectedSectionIndex=0;editingResourceId=null;editingReleaseId=null;refreshEditorLists();loadProject();loadSite();loadAI();loadDocument();}
// Live preview and editable image placement. The stored draft keeps file paths,
// while preview copies use temporary URLs for files held in this browser.
const previewAssetURLs=new Map();
let livePreviewTimer=null,previewExpanded=false,previewImageFocus=null;
function mediaNumber(value,fallback,min,max){const n=Number(value);return Number.isFinite(n)?Math.min(max,Math.max(min,n)):fallback;}
function imageLayout(value={}){value=value&&typeof value==='object'?value:{};const width=mediaNumber(value.width,100,10,100);return {width,offsetX:mediaNumber(value.offsetX,0,0,100-width),spaceTop:mediaNumber(value.spaceTop,0,0,200),height:mediaNumber(value.height,0,0,1000),fit:value.fit==='cover'?'cover':'contain',positionX:mediaNumber(value.positionX,50,0,100),positionY:mediaNumber(value.positionY,50,0,100)};}
function previewAsset(path){const asset=pendingAssets.get(path);if(!asset)return path;if(!previewAssetURLs.has(path))previewAssetURLs.set(path,URL.createObjectURL(new Blob([asset.bytes],{type:asset.type})));return previewAssetURLs.get(path);}
function imageLayoutFields(layout,prefix){const l=imageLayout(layout);return `<div class="image-layout-controls"><label>너비 (%)<input type="number" min="10" max="100" step="1" data-image-prop="width" value="${l.width}" aria-label="${prefix} 너비 (%)"></label><label>왼쪽 위치 (%)<input type="number" min="0" max="90" step="1" data-image-prop="offsetX" value="${l.offsetX}" aria-label="${prefix} 왼쪽 위치 (%)"></label><label>위 여백 (px)<input type="number" min="0" max="200" data-image-prop="spaceTop" value="${l.spaceTop}" aria-label="${prefix} 위 여백 (px)"></label><label>높이 (px, 0=자동)<input type="number" min="0" max="1000" data-image-prop="height" value="${l.height}" aria-label="${prefix} 높이 (px)"></label><label>표시 방식<select data-image-prop="fit" aria-label="${prefix} 표시 방식"><option value="contain" ${l.fit==='contain'?'selected':''}>전체 보이기</option><option value="cover" ${l.fit==='cover'?'selected':''}>영역 채우기</option></select></label></div><div class="image-align-controls" role="group" aria-label="${prefix} 정렬"><button type="button" data-image-align="left">왼쪽</button><button type="button" data-image-align="center">가운데</button><button type="button" data-image-align="right">오른쪽</button></div>`;}
function renderImageEditor(b,index){const l=imageLayout(b.layout),prefix='이미지 '+(index+1);return `<div class="editor-image-block" data-image-index="${index}"><label class="form-field">이미지 파일 첨부<input type="file" accept="image/png,image/jpeg,image/webp" data-block-media-upload="image" data-block="${index}"></label><div class="image-placement-stage"><div class="placement-image" style="width:${l.width}%;margin-left:${l.offsetX}%;margin-top:${l.spaceTop}px" data-drag-image="move"><img src="${esc(previewAsset(b.src))}" alt="${esc(b.alt||'')}" draggable="false" style="height:${l.height?l.height+'px':'auto'};object-fit:${l.fit}"><button type="button" class="image-resize-handle" data-drag-image="resize" aria-label="${prefix} 크기 조절 · 아래 너비 입력으로도 조절 가능"></button></div></div><p class="image-help">이미지를 끌어 위치를 옮기거나 오른쪽 아래 손잡이로 너비를 조절하세요.</p><label class="form-field">이미지 경로<input data-image-prop="src" value="${esc(b.src)}" aria-label="${prefix} 경로"></label><label class="form-field">대체 텍스트<input data-image-prop="alt" value="${esc(b.alt||'')}" aria-label="${prefix} 대체 텍스트"></label><label class="form-field">설명<input data-image-prop="caption" value="${esc(b.caption||'')}" aria-label="${prefix} 설명"></label>${imageLayoutFields(l,prefix)}</div>`;}
function readImageBlock(el){const values={};for(const field of el.querySelectorAll('[data-image-prop]'))values[field.dataset.imageProp]=field.value;return {index:Number(el.dataset.imageIndex),src:safePath(values.src),alt:values.alt||'',caption:values.caption||'',layout:imageLayout(values)};}
function coverFields(form){return {cover:safePath(formField(form,'cover').value),coverLayout:{fit:formField(form,'coverFit').value==='contain'?'contain':'cover',positionX:mediaNumber(formField(form,'coverX').value,50,0,100),positionY:mediaNumber(formField(form,'coverY').value,50,0,100)}};}
function loadCoverFields(form,row){const l=row.coverLayout||{};formField(form,'cover').value=row.cover||'';formField(form,'coverFit').value=l.fit==='contain'?'contain':'cover';formField(form,'coverX').value=l.positionX??50;formField(form,'coverY').value=l.positionY??50;if(form.id==='project-form')formField(form,'heroWidth').value=l.heroWidth??(row.id==='ww'?67:47);}
// Preview accepts incomplete typing. Save/export still uses the strict validators.
function previewPath(value,fallback=''){try{return safePath(value);}catch{return fallback;}}
function previewPairs(value){return String(value).split('\n').filter(line=>line.trim()).map(line=>{const split=line.indexOf('|');return split<0?[line,'']:[line.slice(0,split).trim(),line.slice(split+1).trim()];});}
function previewCover(form,row){return {cover:previewPath(formField(form,'cover').value,row.cover),coverLayout:{...row.coverLayout,fit:formField(form,'coverFit').value==='contain'?'contain':'cover',positionX:mediaNumber(formField(form,'coverX').value,50,0,100),positionY:mediaNumber(formField(form,'coverY').value,50,0,100)}};}
function currentPreviewData(){
 const next=clone(draft),active=document.querySelector('.editor-section:not([hidden])')?.id;
 if(active==='ai-panel'){next.site.aiDevelopment=readAI();}else if(active==='projects-panel'){
  const form=$('#project-form'),p=next.projects.find(p=>p.id===selectedProjectId),read=name=>formField(form,name).value;
  p.name=read('name');p.genre=read('genre');p.cardText=read('cardText');p.description=read('tagline');
  p.brief={...(p.brief||original.projects.find(base=>base.id===p.id)?.brief),title:read('title').split('\n'),label:read('label'),tagline:read('tagline'),concept:read('concept'),points:parseLines(read('points')),steps:previewPairs(read('steps')),build:previewPairs(read('build'))};
  Object.assign(p,previewCover(form,p));p.coverLayout.heroWidth=mediaNumber(read('heroWidth'),p.id==='ww'?67:47,25,80);
  for(const name of ['heading','kicker','contactEmail'])next.site[name]=formField($('#site-form'),name).value;
 }else if(active==='documents-panel'){
  const form=$('#document-form'),doc=next.documents.find(d=>d.id===selectedDocumentId),section=doc.sections[selectedSectionIndex];
  doc.title=formField(form,'title').value;doc.kind=formField(form,'kind').value;section.title=formField(form,'sectionTitle').value;Object.assign(doc,previewCover(form,doc));
  for(const el of document.querySelectorAll('.doc-text-edit')){const b=section.blocks[Number(el.dataset.block)];if(b?.type==='text'){b.text=el.value;const variant=document.querySelector('.doc-text-style[data-block="'+el.dataset.block+'"]')?.value;if(['paragraph','heading'].includes(variant))b.variant=variant;else delete b.variant;}}
  for(const el of document.querySelectorAll('.doc-cell-edit')){const rows=section.blocks[Number(el.dataset.block)]?.rows;if(rows?.[Number(el.dataset.row)])rows[Number(el.dataset.row)][Number(el.dataset.col)]=el.value;}
  for(const el of document.querySelectorAll('.editor-video-block')){const b=section.blocks[Number(el.dataset.imageIndex)];if(b?.type!=='video')continue;const values={};for(const field of el.querySelectorAll('[data-image-prop]'))values[field.dataset.imageProp]=field.value;b.src=previewPath(values.src,b.src);b.title=values.title||'';b.caption=values.caption||'';b.layout=imageLayout(values);}for(const el of document.querySelectorAll('.editor-link-block')){const b=section.blocks[Number(el.dataset.linkIndex)];if(b?.type!=='link')continue;const values={};for(const field of el.querySelectorAll('[data-link-prop]'))values[field.dataset.linkProp]=field.value;try{b.url=safeDocumentLink(values.url);}catch{}b.label=values.label||'';b.description=values.description||'';}for(const el of document.querySelectorAll('.editor-image-block')){const b=section.blocks[Number(el.dataset.imageIndex)];if(b?.type!=='image')continue;const values={};for(const field of el.querySelectorAll('[data-image-prop]'))values[field.dataset.imageProp]=field.value;b.src=previewPath(values.src,b.src);b.alt=values.alt||'';b.caption=values.caption||'';b.layout=imageLayout(values);}
 }
 return next;
}
function resolvePreviewMedia(data){if(data.site.aiDevelopment?.markdown)data.site.aiDevelopment.markdown=data.site.aiDevelopment.markdown.replace(/(!\[[^\]]*\]\()([^\s)]+)(\))/g,(_,start,path,end)=>start+previewAsset(path)+end);for(const p of data.projects)p.cover=previewAsset(p.cover);for(const r of data.resources)if(r.preview)r.preview=previewAsset(r.preview);for(const d of data.documents){if(d.cover)d.cover=previewAsset(d.cover);for(const s of d.sections)for(const b of s.blocks)if(b.type==='image'||b.type==='video')b.src=previewAsset(b.src);}return data;}
const LIVE_PREVIEW_KEY='project-archive-live-preview-v1';
const previewSession=crypto.randomUUID();
const livePreviewChannel=typeof window.BroadcastChannel==='function'?new window.BroadcastChannel('project-archive-live-preview'):null;
let previewRevision=0,lastPreviewRevision='';
function sendLivePreview(){
 try{
  const sourceData=currentPreviewData(),data=resolvePreviewMedia(clone(sourceData)),mode=$('#preview-page').value;
  const route=mode==='ai-development'?'ai-development':mode==='overview'?'overview':mode==='documents'?'documents?project='+data.documents.find(d=>d.id===selectedDocumentId).project:mode==='document'?'document/'+selectedDocumentId:'project/'+selectedProjectId;
  const payload={type:'archive-live-preview',revision:previewSession+':'+(++previewRevision),data,route,focus:mode==='document'?previewImageFocus:null,css:stagedFiles.get('styles.css')||''};
  lastPreviewRevision=payload.revision;
  $('#live-preview-status').textContent='미리보기 반영 중…';
  $('#open-live-preview').setAttribute('href','./index.html?draft=1#'+route);
  $('#live-preview-frame')?.contentWindow?.postMessage(payload,new URL(location.href).origin);
  livePreviewChannel?.postMessage(payload);
  // Separate-window fallback and first-load snapshot. Never overwrite the saved draft.
  try{localStorage.setItem(LIVE_PREVIEW_KEY,JSON.stringify({...payload,data:sourceData,updatedAt:Date.now()}));}catch{}
 }catch(error){$('#live-preview-status').textContent='미리보기를 표시하지 못했습니다: '+error.message;}
}
function scheduleLivePreview(){
 if(livePreviewTimer!==null)return;
 // Throttle instead of debounce: continuous typing and dragging keep updating.
 livePreviewTimer=setTimeout(()=>{livePreviewTimer=null;sendLivePreview();},80);
}
function initPreviewSync(){
 window.addEventListener('message',event=>{
  if(event.source!==$('#live-preview-frame')?.contentWindow||event.origin!==new URL(location.href).origin)return;
  if(event.data?.type==='archive-preview-ready'){scheduleLivePreview();return;}
  if(event.data?.type==='archive-preview-applied'&&event.data.revision===lastPreviewRevision)$('#live-preview-status').textContent='실시간 반영됨 · 저장 전 내용';
 });
 if(livePreviewChannel)livePreviewChannel.onmessage=event=>{if(event.data?.type==='archive-preview-request')scheduleLivePreview();};
 $('#open-live-preview').addEventListener('click',sendLivePreview);
}
async function attachEditorImage(file,target){if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('PNG·JPEG·WebP 이미지를 선택해 주세요.');const path=await stageAsset(file);if(target==='body'){insertDocumentImage(path,file.name.replace(/\.[^.]+$/,''));}else{formField($('#'+(target==='document'?'document':'project')+'-form'),'cover').value=path;status('이미지를 첨부했습니다. 크기·초점을 조절하고 초안을 저장해 주세요.');}scheduleLivePreview();}
function insertDocumentImage(src,alt=''){const path=safePath(src);if(!path)throw Error('이미지 주소를 입력해 주세요.');if(!saveDocumentFields(true))return false;const blocks=draft.documents.find(d=>d.id===selectedDocumentId).sections[selectedSectionIndex].blocks,at=Math.round(mediaNumber(documentInsertPosition,blocks.length,0,blocks.length)),block={...newContentBlock('image'),src:path,alt};const next=insertContent(draft,selectedDocumentId,selectedSectionIndex,at,block);documentInsertPosition=at+1;if(!persist(next,'본문 이미지를 추가했습니다.'))return false;loadDocument();scheduleLivePreview();return true;}
function updatePlacementStage(el){let b;try{b=readImageBlock(el);}catch{return;}const l=b.layout,placed=el.querySelector('.placement-image'),img=placed.querySelector('img');placed.style.width=l.width+'%';placed.style.marginLeft=l.offsetX+'%';placed.style.marginTop=l.spaceTop+'px';img.src=previewAsset(b.src);img.style.height=l.height?l.height+'px':'auto';img.style.objectFit=l.fit;for(const key of ['width','offsetX','spaceTop','height'])el.querySelector('[data-image-prop="'+key+'"]').value=l[key];}
