 $('#expand-live-preview').addEventListener('click',e=>{previewExpanded=!previewExpanded;$('#live-preview-panel').classList.toggle('expanded',previewExpanded);e.target.textContent=previewExpanded?'미리보기 축소':'크게 보기';e.target.setAttribute('aria-pressed',String(previewExpanded));});
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&previewExpanded)$('#expand-live-preview').click();});
 document.addEventListener('input',e=>{const block=e.target.closest('.editor-image-block');if(block){previewImageFocus=selectedSectionIndex+'-'+block.dataset.imageIndex;updatePlacementStage(block);}else{const field=e.target.closest('.doc-text-edit,.doc-cell-edit'),media=e.target.closest('.editor-video-block'),link=e.target.closest('.editor-link-block');previewImageFocus=field?selectedSectionIndex+'-'+field.dataset.block:media?selectedSectionIndex+'-'+media.dataset.imageIndex:link?selectedSectionIndex+'-'+link.dataset.linkIndex:null;}if(e.target.closest('#project-form,#document-form,#site-form,#ai-form'))scheduleLivePreview();});
 document.addEventListener('change',e=>{if(['document-select','section-select','project-select'].includes(e.target.id))previewImageFocus=null;if(e.target.closest('.editor-image-block'))updatePlacementStage(e.target.closest('.editor-image-block'));scheduleLivePreview();});
 document.addEventListener('click',e=>{const align=e.target.closest('[data-image-align]');if(align){const block=align.closest('.editor-image-block,.editor-video-block');previewImageFocus=selectedSectionIndex+'-'+block.dataset.imageIndex;const width=readImageBlock(block).layout.width;block.querySelector('[data-image-prop="offsetX"]').value=align.dataset.imageAlign==='left'?0:align.dataset.imageAlign==='right'?100-width:(100-width)/2;if(block.classList.contains('editor-image-block'))updatePlacementStage(block);scheduleLivePreview();}const move=e.target.closest('[data-move-doc-block]');if(move){if(!saveDocumentFields(true))return;const next=clone(draft),blocks=next.documents.find(d=>d.id===selectedDocumentId).sections[selectedSectionIndex].blocks,from=Number(move.dataset.block),to=from+Number(move.dataset.moveDocBlock);if(to>=0&&to<blocks.length){[blocks[from],blocks[to]]=[blocks[to],blocks[from]];persist(next,'본문 순서를 바꿨습니다.');loadDocument();}}const tab=e.target.closest('[data-editor-tab]');if(tab){if(tab.dataset.editorTab==='ai-panel')$('#preview-page').value='ai-development';if(tab.dataset.editorTab==='documents-panel')$('#preview-page').value='document';if(tab.dataset.editorTab==='projects-panel')$('#preview-page').value='project';scheduleLivePreview();}});
